'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('de-DE', {style:'currency',currency:'EUR'}).format(cents / 100);
const storageKey = 'la-mela-doro-cart-v1';
let menu, restaurant, items = new Map(), cart = [], group = 'food', category = 'pizze', filters = new Set(), pendingVariant, toastTimer, storageAvailable = true;
const normalize = value => String(value).toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ß/g,'ss');
const keyFor = (id, variant) => `${id}:${variant}`;
const quantityOf = id => cart.filter(row => row.id === id).reduce((sum, row) => sum + row.quantity, 0);
const totals = () => cart.reduce((result, row) => { const item = items.get(row.id); const price = item?.variants[row.variant]?.priceCents; if (Number.isInteger(price)) { result.quantity += row.quantity; result.cents += row.quantity * price; } return result; }, {quantity:0,cents:0});
function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('visible'), 3000); }
function persist() { try { localStorage.setItem(storageKey, JSON.stringify(cart)); } catch { if(storageAvailable)toast('Dein Browser kann die Auswahl nicht dauerhaft speichern.'); storageAvailable = false; } }
function restore() { try { const value=JSON.parse(localStorage.getItem(storageKey) || '[]'); if(Array.isArray(value)) cart=value.slice(0,264).filter(row => row && items.has(row.id) && Number.isInteger(row.variant) && items.get(row.id).variants[row.variant] && Number.isInteger(row.quantity) && row.quantity>0 && row.quantity<=99).reduce((rows,row)=>{const match=rows.find(r=>r.id===row.id&&r.variant===row.variant);if(match)match.quantity=Math.min(99,match.quantity+row.quantity);else rows.push({id:row.id,variant:row.variant,quantity:row.quantity});return rows;},[]); } catch {cart=[];} }
function updateCounts() {const total=totals();$$('[data-cart-count]').forEach(el=>el.textContent=total.quantity);$$('[data-cart-total]').forEach(el=>el.textContent=money(total.cents));$('.floating-cart').hidden=!total.quantity;$('#mobile-cart-label').textContent=String(total.quantity);$('#mobile-cart-label').hidden=!total.quantity;$$('.action-rail [data-cart-count]').forEach(el=>el.hidden=!total.quantity);$$('[data-cart]').forEach(el=>el.setAttribute('aria-label',`Warenkorb öffnen, ${total.quantity} Artikel`));}
function showDialog(dialog) { if (!dialog.open) dialog.showModal(); document.body.classList.add('dialog-open'); }
function closeDialog(dialog) { dialog.close(); }
$$('dialog').forEach(dialog => { dialog.addEventListener('close',()=>{document.body.classList.toggle('dialog-open',!!$('dialog[open]'));if(dialog.id==='mobile-nav')$('#menu-toggle').setAttribute('aria-expanded','false');}); dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}); });
$$('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$('#menu-toggle').addEventListener('click',()=>{$('#menu-toggle').setAttribute('aria-expanded','true');showDialog($('#mobile-nav'));});
$$('#mobile-nav a').forEach(link=>link.addEventListener('click',()=>closeDialog($('#mobile-nav'))));
window.addEventListener('scroll',()=>$('#header').classList.toggle('scrolled',window.scrollY>20),{passive:true});
function saveChange() {
 const focused=document.activeElement;
 const attribute=['data-add','data-decrease','data-cart-change','data-remove'].find(name=>focused?.hasAttribute(name));
 const value=attribute?focused.getAttribute(attribute):null;
 persist();updateCounts();renderMenu();renderCart();
 if(attribute){let next=$$(`[${attribute}]`).find(el=>el.getAttribute(attribute)===value);
  if(!next&&attribute==='data-decrease')next=$$('[data-add]').find(el=>el.getAttribute('data-add')===value);
  if(!next&&$('#cart-dialog').open)next=$('[data-cart-change]', $('#cart-items'))||$('[data-close]',$('#cart-dialog'));
  next?.focus({preventScroll:true});
 }
}
function add(id, variant=0) {const item=items.get(id);if(!item?.variants[variant])return; const row=cart.find(r=>r.id===id&&r.variant===variant); if(row){if(row.quantity>=99){toast('Maximal 99 Stück pro Auswahl.');return;}row.quantity++;}else cart.push({id,variant,quantity:1});saveChange();toast(`${item.name} hinzugefügt`);}
function changeQuantity(id,variant,delta) { const row=cart.find(r=>r.id===id&&r.variant===variant);if(!row)return;row.quantity=Math.min(99,row.quantity+delta);cart=cart.filter(r=>r.quantity>0);saveChange(); }
function askVariant(id) {const item=items.get(id);if(!item?.variants.length)return;if(item.variants.length===1){add(id);return;}pendingVariant=id;$('#variant-title').textContent=item.name;$('#variant-options').innerHTML=item.variants.map((variant,i)=>`<button class="variant-option" data-variant="${i}"><span>${esc(variant.label)}</span><strong>${money(variant.priceCents)}</strong></button>`).join('');showDialog($('#variant-dialog'));}
$('#variant-options').addEventListener('click',event=>{const button=event.target.closest('[data-variant]');if(!button)return;add(pendingVariant,Number(button.dataset.variant));closeDialog($('#variant-dialog'));});
function itemMarkup(item) {const min=item.variants.length?Math.min(...item.variants.map(v=>v.priceCents)):null;const qty=quantityOf(item.id);const soleVariant=item.variants.length===1;return `<article class="menu-item"><div><h4 class="item-name"><span class="item-number">${item.number?`NR. ${esc(item.number)}`:''}</span>${esc(item.name)}</h4>${item.description?`<p class="item-description">${esc(item.description)}</p>`:''}<div class="item-meta">${item.tags.map(tag=>`<span class="item-tag ${tag==='scharf'?'spicy':''}">${tag==='scharf'?'Scharf':'Vegetarisch'}</span>`).join('')}${item.allergenCodes.length?`<span aria-label="Kennzeichnungen der Originalkarte: ${esc(item.allergenCodes.join(', '))}">${esc(item.allergenCodes.join(', '))}</span>`:''}${soleVariant&&item.variants[0].label!=='Portion'?`<span>${esc(item.variants[0].label)}</span>`:''}</div></div><div class="item-side">${min!==null?`<span class="item-price">${item.variants.length>1?'<small>ab</small>':''}${money(min)}</span>`:'<span class="price-unknown">Preis bitte erfragen</span>'}${min!==null?(soleVariant&&qty?`<div class="menu-quantity"><button data-decrease="${esc(item.id)}" aria-label="Ein ${esc(item.name)} weniger">−</button><span>${qty}</span><button data-add="${esc(item.id)}" aria-label="Ein ${esc(item.name)} hinzufügen">+</button></div>`:`<button class="add-button" data-add="${esc(item.id)}" aria-label="${esc(item.name)} ${item.variants.length>1?'auswählen':'hinzufügen'}">+</button>`):''}</div></article>`;}
function renderCategories() {if(!menu)return;const categories=menu.categories.filter(c=>c.group===group);$('#category-nav').innerHTML=categories.map(c=>`<button data-category="${esc(c.id)}" class="${c.id===category?'active':''}" ${c.id===category?'aria-current="true"':''}><b style="font-weight:inherit">${esc(c.label)}</b><span>${c.items.length}</span></button>`).join('');$$('[data-group]').forEach(button=>{const selected=button.dataset.group===group;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',selected);});$$('[data-filter]').forEach(button=>button.setAttribute('aria-pressed',filters.has(button.dataset.filter)));}
function renderMenu() {if(!menu)return;const query=normalize($('#menu-search').value.trim());const searching=!!query || !!filters.size;const current=menu.categories.find(c=>c.id===category);if(!current)return;$('#category-title').textContent=query?'Deine Suchergebnisse':filters.size?'Deine Auswahl':current.label;$('#category-eyebrow').textContent=query?'IN DER GESAMTEN KARTE':filters.size?'KENNZEICHNUNGEN AUS DER KARTE':current.category;$('#category-note').hidden=searching||!current.note;$('#category-note').textContent=current.note;$('#original-menu').hidden=searching;let count=0;const found=menu.categories.filter(c=>query|| (filters.size?c.group===group:c.id===category)).map(c=>{const matches=c.items.filter(item=>(!query||normalize(`${item.name} ${item.description} ${item.number} ${c.category} ${c.label}`).includes(query))&&[...filters].every(tag=>item.tags.includes(tag)));count+=matches.length;if(!matches.length)return '';return `${searching?`<h4 class="search-category">${esc(c.label)}</h4>${c.note?`<p class="category-note">${esc(c.note)}</p>`:''}`:''}<div class="menu-grid">${matches.map(itemMarkup).join('')}</div>`;}).join('');$('#menu-items').innerHTML=found||'<div class="empty-results"><h4>Kein Gericht gefunden.</h4><p>Versuche einen anderen Suchbegriff oder ändere deine Filter.</p><button class="button button-outline" data-reset-search>Alle Gerichte anzeigen</button></div>';$('#result-count').textContent=`${count} ${count===1?'Gericht / Getränk':'Gerichte & Getränke'}`;}
function setCategory(id,scroll=false) {const selected=menu?.categories.find(c=>c.id===id);if(!selected)return;category=id;group=selected.group;filters.clear();$('#menu-search').value='';renderCategories();renderMenu();if(scroll)$('#speisekarte').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});const tab=$(`[data-category="${id}"]`,$('#category-nav'));if(tab&&innerWidth<=900){const nav=$('#category-nav');nav.scrollLeft=tab.offsetLeft-nav.offsetLeft-10;}}
function renderCart() {const total=totals();$('#cart-summary').hidden=!total.quantity;if(!total.quantity){$('#cart-items').innerHTML='<div class="cart-empty"><h3>Noch Platz für etwas Gutes.</h3><p>Entdecke unsere Speisekarte und stell deine Lieblingsgerichte zusammen.</p><button class="button" data-start-order>Zur Speisekarte</button></div>';return;}$('#cart-items').innerHTML=cart.map(row=>{const item=items.get(row.id);const variant=item.variants[row.variant];return `<article class="cart-row"><div><h3>${esc(item.name)}</h3><small>${item.number?`Nr. ${esc(item.number)} · `:''}${esc(variant.label)} · ${money(variant.priceCents)}</small><div class="cart-row-controls"><div class="menu-quantity"><button data-cart-change="${esc(keyFor(row.id,row.variant))}" data-delta="-1" aria-label="Ein ${esc(item.name)} weniger">−</button><span>${row.quantity}</span><button data-cart-change="${esc(keyFor(row.id,row.variant))}" data-delta="1" aria-label="Ein ${esc(item.name)} mehr">+</button></div><button class="cart-remove" data-remove="${esc(keyFor(row.id,row.variant))}" aria-label="${esc(item.name)} entfernen">Entfernen</button></div></div><strong>${money(row.quantity*variant.priceCents)}</strong></article>`;}).join('');updateCounts();}
function orderText() {return `Hallo, ich möchte folgende Bestellung anfragen:\n\n${cart.map(row=>{const item=items.get(row.id);const variant=item.variants[row.variant];return `${row.quantity} × ${item.name}${variant.label!=='Portion'?` (${variant.label})`:''}${item.number?` [Nr. ${item.number}]`:''} – ${money(row.quantity*variant.priceCents)}`;}).join('\n')}\n\nGesamt laut Karte: ${money(totals().cents)}\nName:\nWeitere Details bitte telefonisch besprechen.`;}
$$('[data-cart]').forEach(button=>button.addEventListener('click',()=>{renderCart();showDialog($('#cart-dialog'));}));
$('#cart-items').addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-start-order')){closeDialog($('#cart-dialog'));$('#speisekarte').scrollIntoView();return;}const key=button.dataset.cartChange||button.dataset.remove;if(!key)return;const [id,variant]=key.split(':');if(button.hasAttribute('data-remove')){cart=cart.filter(r=>!(r.id===id&&r.variant===Number(variant)));saveChange();}else changeQuantity(id,Number(variant),Number(button.dataset.delta));});
$('#clear-cart').addEventListener('click',()=>{cart=[];saveChange();toast('Deine Auswahl wurde geleert.');});
$('#copy-order').addEventListener('click',async()=>{if(!cart.length)return;try{await navigator.clipboard.writeText(orderText());toast('Auswahl kopiert – bitte telefonisch bestätigen.');}catch{const text=document.createElement('textarea');text.value=orderText();text.style.cssText='position:fixed;inset:10px;width:1px;height:1px';$('#cart-dialog').append(text);text.select();const copied=document.execCommand('copy');text.remove();toast(copied?'Auswahl kopiert.':'Kopieren ist in diesem Browser nicht verfügbar.');}});
$('#storage-info').addEventListener('click',()=>showDialog($('#storage-dialog')));
$('#delete-storage').addEventListener('click',()=>{cart=[];try{localStorage.removeItem(storageKey);}catch{}updateCounts();renderMenu();renderCart();closeDialog($('#storage-dialog'));toast('Gespeicherte Auswahl gelöscht.');});
$('#menu-search').addEventListener('input',renderMenu);
$$('[data-group]').forEach(button=>button.addEventListener('click',()=>{if(!menu)return;setCategory(menu.categories.find(c=>c.group===button.dataset.group).id);}));
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const tag=button.dataset.filter;if(filters.has(tag))filters.delete(tag);else filters.add(tag);renderCategories();renderMenu();}));
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.category){setCategory(button.dataset.category,!button.closest('#category-nav'));return;}if(button.dataset.add){askVariant(button.dataset.add);return;}if(button.dataset.decrease){changeQuantity(button.dataset.decrease,0,-1);return;}if(button.hasAttribute('data-reset-search')){filters.clear();$('#menu-search').value='';renderCategories();renderMenu();return;}if(button.dataset.lightbox){$('#source-page').hidden=true;showLightbox(button.dataset.lightbox,button.dataset.caption);}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!$('dialog[open]')&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){event.preventDefault();$('#speisekarte').scrollIntoView();$('#menu-search').focus({preventScroll:true});}});
function showLightbox(src,caption) {$('#lightbox-image').src=src;$('#lightbox-image').alt=caption;$('#lightbox-caption').textContent=caption;showDialog($('#lightbox'));}
function showSource(page) {showLightbox(`assets/original-menu/page-${String(page).padStart(2,'0')}.webp`,`Originalkarte · Seite ${page} von 25`);}
$('#source-page').innerHTML=Array.from({length:25},(_,i)=>`<option value="${i+1}">Originalkarte · Seite ${i+1}</option>`).join('');
$('#source-page').addEventListener('change',event=>showSource(Number(event.target.value)));
$('#original-menu').addEventListener('click',()=>{if(!menu)return;const current=menu.categories.find(c=>c.id===category);const page=current.items[0].sourcePage;$('#source-page').hidden=false;$('#source-page').value=page;showSource(page);});
function renderHours(){if(!restaurant?.openingHours)return;$('#opening-hours').innerHTML=restaurant.openingHours.map(day=>`<div><dt>${esc(day.day)}</dt><dd>${day.periods.map(p=>`${esc(p[0])} – ${esc(p[1])}`).join('<br>')}</dd></div>`).join('');}
async function loadMenu() {$('#menu-error').hidden=true;try{const responses=await Promise.all([fetch('data/menu.json'),fetch('data/restaurant.json')]);if(responses.some(r=>!r.ok))throw new Error('Daten nicht verfügbar');[menu,restaurant]=await Promise.all(responses.map(r=>r.json()));if(!Array.isArray(menu.categories))throw new Error('Menüdaten ungültig');items=new Map(menu.categories.flatMap(c=>c.items.map(item=>[item.id,item])));restore();renderCategories();renderMenu();renderCart();renderHours();updateCounts();}catch(error){$('#menu-error').hidden=false;$('#result-count').textContent='';console.error(error);}}
$('#retry-menu').addEventListener('click',loadMenu);
loadMenu();
